import{_ as t,o,c as s,a5 as r}from"./chunks/framework.DukzBDYY.js";const a="/images/run-sheet.jpg",i="/images/print.jpg",d="/images/packing-list.jpg",n="/images/export.jpg",h="/images/widget.jpg",y=JSON.parse('{"title":"The Run Sheet","description":"","frontmatter":{},"headers":[],"relativePath":"guides/run-sheet.md","filePath":"guides/run-sheet.md"}'),l={name:"guides/run-sheet.md"};function p(c,e,g,m,u,k){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="the-run-sheet" tabindex="-1">The Run Sheet <a class="header-anchor" href="#the-run-sheet" aria-label="Permalink to &quot;The Run Sheet&quot;">​</a></h1><p><strong>Delivery Slots → Run sheet</strong> shows a day’s booked orders, grouped by slot.</p><p><img src="'+a+'" alt="The run sheet for Tuesday 17 November: six slot cards showing how full each is, and eight orders grouped by time with customer, phone, address, zone, items and status; one is Delivered, the others have a Mark delivered button"></p><ul><li><strong>The date</strong> starts at today. Use the arrows to move a day, or <strong>Today</strong> to come back.</li><li><strong>The shipping method</strong> menu shows one method, or all of them.</li><li><strong>The slot cards</strong> show how many orders each window has, out of its limit, when one method is shown.</li><li><strong>The orders</strong> are grouped by slot, then sorted by zone and suburb, which is roughly the order a driver visits them. Click an order number to open it.</li></ul><p>Only completed orders are listed. Carts that are holding a slot aren’t, though they count towards how full a slot is at checkout.</p><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Order</strong></td><td>The order’s reference, or its short number</td></tr><tr><td><strong>Customer</strong></td><td>The shipping address’s name, and its phone number. Without a Phone field on addresses, the customer’s email</td></tr><tr><td><strong>Address</strong></td><td>The shipping address</td></tr><tr><td><strong>Zone</strong></td><td>The <a href="/guides/zones">zone</a> the address is in</td></tr><tr><td><strong>Items</strong></td><td>How many items the order has</td></tr><tr><td><strong>Note</strong></td><td>An order field you choose with <code>noteField</code> in the <a href="/getting-started/configuration">config file</a>, such as delivery instructions</td></tr></tbody></table><p>To show phone numbers, add a Phone field (handle <code>phone</code>) to addresses under <strong>Settings → Addresses</strong> and ask for it at checkout.</p><h2 id="print" tabindex="-1">Print <a class="header-anchor" href="#print" aria-label="Permalink to &quot;Print&quot;">​</a></h2><p><strong>Print</strong> opens a plain page for the day and prints it, starting each slot on a new page so each driver gets their own.</p><p><img src="'+i+'" alt="The printed run sheet: Run sheet, Tuesday 17 November 2026, Local delivery, 8 orders, with the orders grouped by slot"></p><h2 id="marking-orders-delivered" tabindex="-1">Marking orders delivered <a class="header-anchor" href="#marking-orders-delivered" aria-label="Permalink to &quot;Marking orders delivered&quot;">​</a></h2><p>Each order has a <strong>Status</strong> column with its Commerce order status. <strong>Mark delivered</strong> sets the order to your <em>Delivered</em> status, so the team can tick orders off as drivers report back, and the order’s status history shows who did it.</p><p>The button shows when:</p><ul><li>your store has an order status with the handle <code>delivered</code> (create it in <strong>Commerce → Store Management → Order Statuses</strong>), or the handle you set with <code>deliveredStatus</code> in the <a href="/getting-started/configuration">config file</a>;</li><li>the user can edit orders.</li></ul><p>Give the status an email in Commerce, such as “Your order has been delivered”, and customers are told automatically.</p><h2 id="packing-list" tabindex="-1">Packing list <a class="header-anchor" href="#packing-list" aria-label="Permalink to &quot;Packing list&quot;">​</a></h2><p>The <strong>Packing list</strong> tab adds up the day’s orders: how many of each item, by slot. Pack the 8am orders first, or bake the right number of loaves.</p><p><img src="'+d+'" alt="The packing list for Tuesday 17 November: four items with their quantity in each slot, such as Seasonal veg box: 2 at 8 – 10am, 3 at 10am – 12pm, 1 at 4 – 6pm, 6 in total"></p><p><strong>Print</strong> on this tab prints the packing list.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p><strong>Export…</strong> downloads a CSV for a day or a date range, such as next week:</p><p><img src="'+n+`" alt="The Export page: From and To dates, a shipping method, and a choice of Orders or Packing list"></p><ul><li><strong>Orders:</strong> Date, Slot, Order, Customer, Email, Phone, Address, Suburb, Postcode, Zone, Items, Total, Shipping method, and Note when it’s set. Import it into a routing app or a spreadsheet.</li><li><strong>Packing list:</strong> each item with its SKU, its quantity in each slot, and the total.</li></ul><p>Values that start with <code>=</code>, <code>+</code>, <code>-</code> or <code>@</code>, such as a name a customer typed, are prefixed with an apostrophe so spreadsheets don’t run them as formulas.</p><h3 id="from-the-command-line" tabindex="-1">From the command line <a class="header-anchor" href="#from-the-command-line" aria-label="Permalink to &quot;From the command line&quot;">​</a></h3><p>The same exports, for scripts and scheduled jobs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delivery-slots/export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from=tomorrow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output=deliveries.csv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delivery-slots/export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from=2026-11-17</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to=2026-11-23</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type=packing</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--from</code></td><td>The first day: a date, <code>today</code> or <code>tomorrow</code>. Default: today</td></tr><tr><td><code>--to</code></td><td>The last day. Default: the same as <code>--from</code></td></tr><tr><td><code>--method</code></td><td>A shipping method handle. Default: every method with slots</td></tr><tr><td><code>--type</code></td><td><code>orders</code> (default) or <code>packing</code></td></tr><tr><td><code>--output</code></td><td>The file to write. Without it, the CSV is printed</td></tr></tbody></table><h2 id="dashboard-widget" tabindex="-1">Dashboard widget <a class="header-anchor" href="#dashboard-widget" aria-label="Permalink to &quot;Dashboard widget&quot;">​</a></h2><p>Add the <strong>Delivery Slots</strong> widget to the dashboard to see how full today’s and tomorrow’s slots are. Choose one shipping method in its settings, or show them all.</p><p><img src="`+h+'" alt="The Delivery Slots widget: today’s two windows for Local delivery with how many are booked, and tomorrow with no delivery times"></p><h2 id="on-the-orders-page" tabindex="-1">On the Orders page <a class="header-anchor" href="#on-the-orders-page" aria-label="Permalink to &quot;On the Orders page&quot;">​</a></h2><p>In <strong>Commerce → Orders</strong>:</p><ul><li>Add the <strong>Delivery time</strong> column from the table’s column settings.</li><li>Filter by <strong>Delivery date</strong>, such as <em>Tomorrow</em> or a date range, to find the orders for a day.</li></ul><h2 id="who-can-see-it" tabindex="-1">Who can see it <a class="header-anchor" href="#who-can-see-it" aria-label="Permalink to &quot;Who can see it&quot;">​</a></h2><p>Users need the <strong>View the run sheet</strong> permission.</p>',37)])])}const f=t(l,[["render",p]]);export{y as __pageData,f as default};
